        if (codigo == null) throw new ErroCheckout("MODALIDADE_INVALIDA");
        var sup = REGISTRO.get(codigo);
        if (sup == null) throw new ErroCheckout("MODALIDADE_INVALIDA");
        return sup.get();
    }
}

